export class Grid {
  /** @param {[number,number,number]} size */
  constructor(size, { dataVersion = DATA_VERSIONS["1.21.4"], entities = null } = {}) {
    this.size = [...size];
    this.dataVersion = dataVersion;
    this.entities = entities;                     // typed NBT list, passed through untouched
    /** @type {Map<string, {pos:number[], block:string, state?:Record<string,string>, nbt?:object}>} */
    this.cells = new Map();
  }

  inBounds(x, y, z) {
    return x >= 0 && y >= 0 && z >= 0 && x < this.size[0] && y < this.size[1] && z < this.size[2];
  }

  /** Set one block (state values become strings, as in NBT). Grows nothing: out of bounds throws. */
  set(x, y, z, block, state, nbt) {
    if (!this.inBounds(x, y, z)) throw new Error(`set out of bounds: ${x},${y},${z} (size ${this.size})`);
    const s = state && Object.keys(state).length
      ? Object.fromEntries(Object.entries(state).map(([k, v]) => [k, String(v)])) : undefined;
    this.cells.set(key(x, y, z), { pos: [x, y, z], block: ns(block), ...(s ? { state: s } : {}), ...(nbt ? { nbt } : {}) });
    return this;
  }

  get(x, y, z) { return this.cells.get(key(x, y, z)); }
  blockAt(x, y, z) { return this.get(x, y, z)?.block ?? "minecraft:air"; }
  isAir(x, y, z) { return AIRS.has(this.blockAt(x, y, z)); }
  unset(x, y, z) { this.cells.delete(key(x, y, z)); return this; }

  /** Fill the inclusive box a..b. */
  fill(a, b, block, state) {
    for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
      for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
        for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) this.set(x, y, z, block, state);
    return this;
  }

  *[Symbol.iterator]() { yield* this.cells.values(); }

  /** Non-air cells. */
  solids() { return [...this.cells.values()].filter((c) => !AIRS.has(c.block)); }

  clone() {
    const g = new Grid(this.size, { dataVersion: this.dataVersion, entities: this.entities });
    for (const c of this.cells.values()) g.cells.set(key(...c.pos), structuredClone(c));
    return g;
  }

  /** Grow the box toward + by `by` = [dx, dy, dz] and/or shift contents by `shift` (to grow toward −). */
  resize(size, shift = [0, 0, 0]) {
    if (shift.some((s) => s)) {
      const moved = new Map();
      for (const c of this.cells.values()) {
        const p = [c.pos[0] + shift[0], c.pos[1] + shift[1], c.pos[2] + shift[2]];
        moved.set(key(...p), { ...c, pos: p });
      }
      this.cells = moved;
    }
    this.size = [...size];
    return this;
  }

  /** [block, count] most common first. */
  census() {
    const m = new Map();
    for (const c of this.solids()) m.set(c.block, (m.get(c.block) || 0) + 1);
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  }

  toTag() {
    const palette = [], index = new Map(), blocks = [];
    for (const c of this.cells.values()) {
      const pk = c.block + JSON.stringify(c.state ? Object.entries(c.state).sort() : []);
      if (!index.has(pk)) {
        index.set(pk, palette.length);
        const e = { Name: t.string(c.block) };
        if (c.state) e.Properties = t.compound(Object.fromEntries(Object.entries(c.state).map(([k, v]) => [k, t.string(v)])));
        palette.push(e);
      }
      const b = { pos: t.list("int", c.pos), state: t.int(index.get(pk)) };
      if (c.nbt) b.nbt = c.nbt;
      blocks.push(b);
    }
    return t.compound({
      DataVersion: t.int(this.dataVersion),
      size: t.list("int", this.size),
      palette: t.list("compound", palette),
      blocks: t.list("compound", blocks),
      entities: this.entities ?? t.list("compound", []),
    });
  }

  /** Write a gzipped structure .nbt, or a Litematica schematic when the path ends in .litematic. */
  save(path) {
    if (/\.litematic$/i.test(path)) return saveLitematic(this, path);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, write(this.toTag()));
    return path;
  }
}

